cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int kD, int kH, int kW,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int Dout, int Hout, int Wout,
    int groups, int Cin_per_group, int Cout_per_group)
{
  constexpr int Threads = 128;
  constexpr int PVec    = 4;

  const int tid = threadIdx.x;

  // Block coordinates
  const int n  = blockIdx.z;
  const int co = blockIdx.y;

  const int g        = co / Cout_per_group;
  const int co_local = co - g * Cout_per_group;
  const int ci_offset = g * Cin_per_group;

  const int K = kD * kH * kW;

  const int P_total = Dout * Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Strides for X (per-n slice): (Cin, D, H, Win)
  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  // Strides for Y (per-n slice): (Cout, Dout, Hout, Wout)
  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, D, H, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn + (int64_t)co * sYc),
      make_shape(Dout, Hout, Wout),
      make_stride(sYd, sYh, Int<1>{})
  );

  // Weight: (Cin, Cout_per_group, K) contiguous
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout_per_group, K),
      make_stride((int64_t)Cout_per_group * K, (int64_t)K, Int<1>{})
  );

  // Shared memory: weight slice for this co, over the group's input channels
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Cin_per_group, K),
      make_stride(K, Int<1>{})
  );

  const int total_w = Cin_per_group * K;
  for (int idx = tid; idx < total_w; idx += Threads) {
    int ci_local = idx / K;
    int k        = idx - ci_local * K;
    int ci       = ci_offset + ci_local;
    sW(ci_local, k) = mW(ci, co_local, k);
  }
  __syncthreads();

  // Precompute output pixel coords for this thread's PVec elements
  int p_idx[PVec];
  int od_arr[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int od = p / (Hout * Wout);
      int rem = p - od * (Hout * Wout);
      int oh = rem / Wout;
      int ow = rem - oh * Wout;
      od_arr[i] = od;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
    } else {
      od_arr[i] = 0;
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  float bias_val = 0.0f;
  if (B != nullptr) {
    bias_val = (float)B[co];
  }

  float acc[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) acc[i] = bias_val;

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_idx[i];
    if (p >= P_total) continue;

    int od = od_arr[i];
    int oh = oh_arr[i];
    int ow = ow_arr[i];

    for (int kd = 0; kd < kD; ++kd) {
      int id_tmp = od + padD - kd;
      if (id_tmp % strideD != 0) continue;
      int id = id_tmp / strideD;
      if (id < 0 || id >= D) continue;

      for (int kh = 0; kh < kH; ++kh) {
        int ih_tmp = oh + padH - kh;
        if (ih_tmp % strideH != 0) continue;
        int ih = ih_tmp / strideH;
        if (ih < 0 || ih >= H) continue;

        for (int kw = 0; kw < kW; ++kw) {
          int iw_tmp = ow + padW - kw;
          if (iw_tmp % strideW != 0) continue;
          int iw = iw_tmp / strideW;
          if (iw < 0 || iw >= Win) continue;

          int k = (kd * kH + kh) * kW + kw;

          float local_acc = 0.0f;
          #pragma unroll 4
          for (int ci_local = 0; ci_local < Cin_per_group; ++ci_local) {
            int ci = ci_offset + ci_local;
            float xval = (float)mX(ci, id, ih, iw);
            float wval = (float)sW(ci_local, k);
            local_acc += xval * wval;
          }
          acc[i] += local_acc;
        }
      }
    }
  }

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_idx[i];
    if (p >= P_total) continue;
    mY(od_arr[i], oh_arr[i], ow_arr[i]) = static_cast<T>(acc[i]);
  }
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int outpadD, int outpadH, int outpadW,
    int groups)
{
  TORCH_CHECK(x.is_cuda() && w.is_cuda(), "x and w must be CUDA tensors");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout/groups, kD, kH, kW]");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  int N   = (int)x_c.size(0);
  int Cin = (int)x_c.size(1);
  int D   = (int)x_c.size(2);
  int H   = (int)x_c.size(3);
  int Win = (int)x_c.size(4);

  TORCH_CHECK(w_c.size(0) == Cin, "w.size(0) must equal Cin");
  int Cout_per_group = (int)w_c.size(1);
  int kD = (int)w_c.size(2);
  int kH = (int)w_c.size(3);
  int kW = (int)w_c.size(4);

  int Cout = Cout_per_group * groups;
  int Cin_per_group = Cin / groups;
  TORCH_CHECK(Cin_per_group * groups == Cin, "Cin must be divisible by groups");

  int Dout = (D - 1) * strideD - 2 * padD + kD + outpadD;
  int Hout = (H - 1) * strideH - 2 * padH + kH + outpadH;
  int Wout = (Win - 1) * strideW - 2 * padW + kW + outpadW;

  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && (int)b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  constexpr int Threads = 128;
  constexpr int PVec = 4;
  const int64_t P_total = (int64_t)Dout * Hout * Wout;
  const int64_t PTile = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)Cout,
      (unsigned)N
  );

  size_t smem_bytes = (size_t)Cin_per_group * (size_t)(kD * kH * kW) * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv_transpose3d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      N, Cin, D, H, Win,
      Cout, kD, kH, kW,
      strideD, strideH, strideW,
      padD, padH, padW,
      Dout, Hout, Wout,
      groups, Cin_per_group, Cout_per_group
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv_transpose3d_ext = load_inline(
    name="cute_conv_transpose3d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Transposed 3D convolution with asymmetric kernel/stride/padding, implemented
    with a single custom CUDA kernel using CuTe tensors for indexing and shared
    memory caching of per-output-channel weight slices.
    """

    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False) -> None:
        super().__init__()

        # Use a reference nn.ConvTranspose3d purely to obtain PyTorch-consistent
        # parameter shapes and initialization.
        ref = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias
        )

        self.weight = nn.Parameter(ref.weight.detach().clone())
        if bias:
            self.bias = nn.Parameter(ref.bias.detach().clone())
        else:
            self.register_parameter("bias", None)

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups

        self._ext = conv_transpose3d_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        strideD, strideH, strideW = self.stride
        padD, padH, padW = self.padding
        outpadD, outpadH, outpadW = self.output_padding

        return self._ext.conv_transpose3d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(strideD), int(strideH), int(strideW),
            int(padD), int(padH), int(padW),
            int(outpadD), int(outpadH), int(outpadW),
            int(self.groups),
        )

