cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Win,
    int Cout, int kD, int kH, int kW,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int Dout, int Hout, int Wout,
    int groups, int Cin_per_group, int Cout_per_group)
{
  constexpr int Threads = 128;
  constexpr int PVec    = 4;

  const int tid = threadIdx.x;

  // Block coordinates
  const int n  = blockIdx.z;
  const int co = blockIdx.y;

  const int g        = co / Cout_per_group;
  const int co_local = co - g * Cout_per_group;
  const int ci_offset = g * Cin_per_group;

  const int K = kD * kH * kW;

  const int P_total = Dout * Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Strides for X (per-n slice): (Cin, D, H, Win)
  const int64_t sXn = (int64_t)Cin * D * H * Win;
  const int64_t sXc = (int64_t)D * H * Win;
  const int64_t sXd = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;

  // Strides for Y (per-n slice): (Cout, Dout, Hout, Wout)
  const int64_t sYn = (int64_t)Cout * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, D, H, Win),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn + (int64_t)co * sYc),
      make_shape(Dout, Hout, Wout),
      make_stride(sYd, sYh, Int<1>{})
  );

  // Weight: (Cin, Cout_per_group, K) contiguous
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(Cin, Cout_per_group, K),
      make_stride((int64_t)Cout_per_group * K, (int64_t)K, Int<1>{})
  );

  // Shared memory: weight slice for this co, over the group's input channels
  extern __shared__ unsigned char smem_raw[];
  T* sW_ptr = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Cin_per_group, K),
      make_stride(K, Int<1>{})
  );

  const int total_w = Cin_per_group * K;
  for (int idx = tid; idx < total_w; idx += Threads) {
    int ci_local = idx / K;
    int k        = idx - ci_local * K;
    int ci       = ci_offset + ci_local;
    sW(ci_local, k) = mW(ci, co_local, k);
  }
  __syncthreads();

  // Precompute output pixel coords for this thread's PVec elements
  int p_idx[PVec];
  int od_arr[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int od = p / (Hout * Wout);
      int rem = p - od * (Hout * Wout);
      int oh = rem / Wout;
      int ow = rem - oh * Wout;
      od_arr[i] = od;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
    } else {
      od_arr[i] = 0;
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  float bias_val = 0.0f;
  if (B != nullptr) {
    bias_val = (float)B[co];
  }

  float acc[PVec];
  #pragma unroll
  for (int i = 0; i < PVec; ++i) acc[i] = bias_val;

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_idx[i];
    if (p >= P_total) continue;

    int od = od_arr[i];
    int oh = oh_arr[i];
    int ow = ow_arr[i];

    for (int kd = 0; kd < kD; ++kd) {
      int id_tmp = od + padD - kd;
      if (id_tmp % strideD != 0) continue;
      int id = id_tmp / strideD;
      if (id < 0 || id >= D) continue;

      for (int kh = 0; kh < kH; ++kh) {
        int ih_tmp = oh + padH - kh;
        if (ih_tmp % strideH != 0) continue;
        int ih = ih_tmp / strideH;
        if (ih < 0 || ih >= H) continue;

        for (int kw = 0; kw < kW; ++kw) {
          int iw_tmp = ow + padW - kw;
          if (iw_tmp % strideW != 0) continue;
          int iw = iw_tmp / strideW;
          if (iw < 0 || iw >= Win) continue;

          int k = (kd * kH + kh) * kW + kw;

          float local_acc = 0.0f;
          #pragma unroll 4
          for (int ci_local = 0; ci_local < Cin_per_group; ++ci_local) {
            int ci = ci_offset + ci_local;
            float xval = (float)mX(ci, id, ih, iw);
            float wval = (float)sW(ci_local, k);
            local_acc += xval * wval;
          }
          acc[i] += local_acc;
        }
      }
    }
  }

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_idx[i];
    if (p >= P_total) continue;
    mY(od_arr[i], oh_arr[i], ow_arr[i]) = static_cast<T>(acc[i]);
  }
}

torch::Tensor conv_transpose3d_forward(
    torch::Tensor x,
    torch::Tensor w,
    c10::optional<torch::Tensor> b,
    int strideD, int strideH, int strideW,
    int padD, int padH, int padW,
    int outpadD, int outpadH, int outpadW,
