  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [Cin, Cout/groups, kD, kH, kW]");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  int N   = (int)x_c.size(0);
  int Cin = (int)x_c.size(1);
  int D   = (int)x_c.size(2);
  int H   = (int)x_c.size(3);
  int Win = (int)x_c.size(4);

  TORCH_CHECK(w_c.size(0) == Cin, "w.size(0) must equal Cin");
  int Cout_per_group = (int)w_c.size(1);
  int kD = (int)w_c.size(2);
  int kH = (int)w_c.size(3);
  int kW = (int)w_c.size(4);

  int Cout = Cout_per_group * groups;
  int Cin_per_group = Cin / groups;
  TORCH_CHECK(Cin_per_group * groups == Cin, "Cin must be divisible by groups");

  int Dout = (D - 1) * strideD - 2 * padD + kD + outpadD;
  int Hout = (H - 1) * strideH - 2 * padH + kH + outpadH;
  int Wout = (Win - 1) * strideW - 2 * padW + kW + outpadW;

  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size computed");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && (int)b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, Cout, Dout, Hout, Wout}, x.options());

  constexpr int Threads = 128;
  constexpr int PVec = 4;
  const int64_t P_total = (int64_t)Dout * Hout * Wout;
  const int64_t PTile = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)Cout,
      (unsigned)N
  );

  size_t smem_bytes = (size_t)Cin_per_group * (size_t)(kD * kH * kW) * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv_transpose3d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      N, Cin, D, H, Win,
      Cout, kD, kH, kW,
      strideD, strideH, strideW,
      padD, padH, padW,
      Dout, Hout, Wout,
      groups, Cin_per_group, Cout_per_group
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
